from collections import deque
from typing import Hashable, TypeVar, Callable, Optional
S=TypeVar("S", bound=Hashable); T=TypeVar("T", bound=Hashable); A=TypeVar("A", bound=Hashable)
def shortest_witness(s0:S,t0:T,alphabet:tuple[A,...],step_s:Callable[[S,A],S],step_t:Callable[[T,A],T],out_s:Callable[[S],object],out_t:Callable[[T],object])->Optional[tuple[A,...]]:
    q=deque([(s0,t0,())]); seen={(s0,t0)}
    while q:
        s,t,w=q.popleft()
        if out_s(s)!=out_t(t): return w
        for a in alphabet:
            pair=(step_s(s,a),step_t(t,a))
            if pair not in seen:
                seen.add(pair); q.append((pair[0],pair[1],w+(a,)))
    return None

