from typing import Callable, Hashable, TypeVar, Optional
I=TypeVar("I", bound=Hashable); O=TypeVar("O")
def distinguishing_input(inputs: tuple[I,...], f: Callable[[I],O], g: Callable[[I],O]) -> Optional[I]:
    return next((i for i in inputs if f(i) != g(i)), None)

from typing import Hashable, TypeVar, Callable
S=TypeVar("S", bound=Hashable); T=TypeVar("T", bound=Hashable); A=TypeVar("A", bound=Hashable)
def greatest_bisimulation(states_s: set[S], states_t: set[T], alphabet: tuple[A, ...], step_s: Callable[[S,A],S], step_t: Callable[[T,A],T], out_s: Callable[[S],object], out_t: Callable[[T],object]) -> set[tuple[S,T]]:
    relation={(s,t) for s in states_s for t in states_t if out_s(s)==out_t(t)}
    while True:
        bad={(s,t) for s,t in relation if any((step_s(s,a),step_t(t,a)) not in relation for a in alphabet)}
        if not bad: return relation
        relation -= bad

